import { createHash } from 'node:crypto';
import { compile as candidateCompile } from '../src/index.ts';
import { compile as parentCompile } from '../../codex-6979-s7o-parent/src/index.ts';
import * as candidateRuntime from '../src/runtime.ts';
import * as parentRuntime from '../../codex-6979-s7o-parent/src/runtime.ts';
const fixtures = {
  typedDecimal: {source:'export function get():(a:number,b:number)=>number{return function(a:number,b:number):number{return a+b;};}',args:[1.5,40.5],expected:42},
  typedRest: {source:'export function get():any{return function(...a:number[]):number{return a.length;};}',args:Array(32).fill(1),expected:32},
  nullArgument: {source:'export function get():any{return function(a:any):number{return a===null?42:-1;};}',args:[null],expected:42},
  nullReceiver: {source:'export function get():any{return function(this:any):number{return this===null?42:-1;};}',args:[],expected:42},
  wideArgc: {source:'export function get():any{return function(a:number,b:number,c:number,d:number,e:number,f:number,g:number,h:number,i:number):number{return arguments.length*100+arguments[31];};}',args:Array(32).fill(1),expected:3201},
};
for(const [lane,compile,runtime] of [['parent',parentCompile,parentRuntime],['candidate',candidateCompile,candidateRuntime],['legacy18-new-runtime',parentCompile,candidateRuntime]] as const){
  for(const [name,fixture]of Object.entries(fixtures)){
    let evidence:any={lane,name,source:fixture.source,expected:fixture.expected};
    try{
      const r=await compile(fixture.source,{skipSemanticDiagnostics:true});
      if(!r.success)throw Error(JSON.stringify(r.errors));
      const imports=runtime.buildCompiledImports(r);
      const{instance}=await WebAssembly.instantiate(r.binary,imports);imports.setInstance?.(instance);
      const ex=runtime.wrapCompiledExports(r,instance) as any;
      evidence={...evidence,bytes:r.binary.length,sha256:createHash('sha256').update(r.binary).digest('hex'),imports:WebAssembly.Module.imports(new WebAssembly.Module(r.binary)).map(x=>x.module+'.'+x.name),slots:(instance.exports as any).$cu?.length};
      const actual=ex.get().apply(null,fixture.args);
      evidence.actual=actual===undefined?'<undefined>':actual;
    }catch(e:any){evidence.error=e?.message??String(e);}
    console.log(JSON.stringify(evidence));
  }
}
